import time
import hmac
import hashlib
import os
import requests
from flask import Flask, request, jsonify

app = Flask(__name__)

# Secret key loaded from environment (injected via task definition)
API_SECRET = os.environ.get('API_SECRET_KEY', 'default-dev-key-do-not-use')

# Token validation with timing vulnerability
def validate_token(provided_token, username):
    """Validate HMAC token for the given username."""
    expected = hmac.new(
        API_SECRET.encode(),
        username.encode(),
        hashlib.sha256
    ).hexdigest()

    # Vulnerable: byte-by-byte comparison leaks timing information
    if len(provided_token) != len(expected):
        return False

    for i in range(len(expected)):
        if provided_token[i] != expected[i]:
            return False
        # Artificial but realistic processing delay per character
        time.sleep(0.001)

    return True


def fetch_task_credentials():
    """Fetch temporary credentials from ECS credential endpoint."""
    cred_uri = os.environ.get('AWS_CONTAINER_CREDENTIALS_RELATIVE_URI', '')
    if cred_uri:
        resp = requests.get(f'http://169.254.170.2{cred_uri}', timeout=2)
        return resp.json()
    return None


@app.route('/api/authenticate', methods=['POST'])
def authenticate():
    """Authenticate user with HMAC token."""
    data = request.get_json()
    if not data or 'username' not in data or 'token' not in data:
        return jsonify({'error': 'Missing username or token'}), 400

    username = data['username']
    token = data['token']

    if validate_token(token, username):
        # On successful auth, return temporary AWS credentials for the user's scope
        creds = fetch_task_credentials()
        if creds:
            return jsonify({
                'authenticated': True,
                'aws_access_key': creds.get('AccessKeyId'),
                'aws_secret_key': creds.get('SecretAccessKey'),
                'aws_session_token': creds.get('Token'),
                'expiration': creds.get('Expiration')
            })
        return jsonify({'authenticated': True, 'message': 'No credentials available'})

    return jsonify({'authenticated': False}), 401


@app.route('/api/health', methods=['GET'])
def health():
    """Health check endpoint."""
    return jsonify({'status': 'healthy', 'version': '2.1.4'})


@app.route('/api/metadata-proxy', methods=['GET'])
def metadata_proxy():
    """Internal endpoint for debugging - proxies to instance metadata."""
    path = request.args.get('path', '/')
    try:
        # Attempts to reach EC2 metadata or ECS metadata
        resp = requests.get(
            f'http://169.254.169.254/latest/meta-data{path}',
            timeout=2,
            headers={'X-Forwarded-For': request.remote_addr}
        )
        return jsonify({'data': resp.text})
    except requests.exceptions.RequestException as e:
        return jsonify({'error': str(e)}), 503


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, threaded=True)
